<section class="portal-card table-wrap"><div class="card-heading"><h3>Invoices</h3></div><table><thead><tr><th>Invoice</th><th>Type</th><th>Subscription / Service</th><th>Amount</th><th>Due Date</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($invoices as $row):?><tr><td><strong><?=htmlspecialchars($row['invoice_number'])?></strong></td><td><?=htmlspecialchars(ucfirst($row['invoice_type']))?></td><td><?=htmlspecialchars($row['subscription_name']??$row['service_name']??$row['project_name']??'—')?></td><td>₹<?=number_format((float)$row['total_amount'],2)?></td><td><?=htmlspecialchars($row['due_date'])?></td><td><span class="status"><?=htmlspecialchars($row['status'])?></span></td><td><div class="invoice-row-actions"><a href="<?=htmlspecialchars(url('/customer/billing/invoices/'.$row['id']))?>">View</a><?php if(in_array($row['status'],['issued','partial','overdue'],true)):?><form method="post" action="<?=htmlspecialchars(url('/customer/billing/invoices/'.$row['id'].'/pay'))?>"><?=csrf_field()?><button class="pay-now" type="submit">Pay ₹<?=number_format(max(0,(float)$row['total_amount']-(float)$row['paid_amount']),2)?></button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table><?php if(!$invoices):?><div class="empty">No invoices have been generated.</div><?php endif;?></section>
